mapper.select:
select a.*, b.fina_user_id as finaUserId, b.fina_user_name as finaUserName, b.fina_user_idcard as finaUserIdcard, b.fina_user_tel as finaUserTel, c.estimate_money as estimateMoney, c.proposal_money as proposalMoney, c.actual_money as actualMoney, c.risk_level as riskLevel, c.real_loan_time as realLoanTime, c.confirm_type as confirmType, c.check_man_id as checkManId, c.check_man_name as checkManName, c.double_check_man_id as doubleCheckManId, c.double_check_man_name as doubleCheckManName, c.check_time as checkTime, c.double_check_time as doubleCheckTime, org.survey_org_id as surveyOrgId, org.id as applicantOrgId, org.survey_org_name as surveyOrgName, org.fina_org_state as finaOrgState, org.org_assign_time as orgAssignTime, org.org_submit_time as orgSubmitTime, org.org_end_time as orgEndTime, org.org_aging as orgAging, invest.survey_user_id as surveyUserId, invest.id as applicantInvestigatorId, invest.survey_user_name as surveyUserName, invest.state as userState, invest.user_assign_time as userAssignTime, invest.user_submit_time as userSubmitTime, invest.org_end_time as userEndTime, invest.user_aging as userAging from fina_applicant_info a left join fina_applicant b on a.fina_id = b.id left join fina_applicant_money c on a.id = c.fina_info_id left join fina_applicant_org org on a.id = org.fina_info_id and org.org_task_type = 1 and org.delete_flag = 0 left join fina_applicant_investigator invest on invest.applicant_org_id = org.id and invest.delete_flag = 0 where a.delete_flag =0 and b.delete_flag =0
group by a.id order by a.id desc
limit #{pageIndex}, #{pageSize}
